            </pre>
        </div>

        <footer style="margin-top: 100px; text-align: center; color: var(--text-dim); font-size: 0.8rem;">
            ◈ CLAI Version Singularity-L1000 ◈ Generated Locally ◈
        </footer>
    </div>
</body>

</html>
